(3580999, 501823, 56828, '<td valign="top">Wow...an amazing photo.  Whay to capture your subject right on the cross hairs.  The beach looks amazing.</td>', 'Wow...an amazing photo.  Whay to capture your subject right on the cross hairs.  The beach looks amazing.', '2007-04-25 10:55:34.000000', NULL, 1),
(3581002, 500161, 62378, '<td valign="top">The title goes perfectly with the shot. I love it</td>', 'The title goes perfectly with the shot. I love it', '2007-04-25 10:56:00.000000', NULL, 1),
