(3582463, 500630, 74209, '<td valign="top">Fabulous.</td>', 'Fabulous.', '2007-04-25 16:48:54.000000', NULL, 1),
(3582475, 501618, 57229, '<td valign="top">Nice colours, giving that strange city-sunlight feel. It works well to have more room in front of the runner than behind, emphasising that she has somewhere to go, but I think you''ve overdone it just to comply with the 1:3 ratio thing. William Blake and  early English Christianity don''t really belong there at all, so the title''s disastrous to my tiny mind.<br/>For the atmosphere and the unusually emotionally close portrait of the runner - 6</td>', 'Nice colours, giving that strange city-sunlight feel. It works well to have more room in front of the runner than behind, emphasising that she has somewhere to go, but I think you''ve overdone it just to comply with the 1:3 ratio thing. William Blake and  early English Christianity don''t really belong there at all, so the title''s disastrous to my tiny mind.For the atmosphere and the unusually emotionally close portrait of the runner - 6', '2007-04-25 16:56:02.000000', NULL, 1),
(3582476, 500046, 57229, '<td valign="top">one third full two thirds empty</td>', 'one third full two thirds empty', '2007-04-25 16:56:58.000000', NULL, 1),
