INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3592202, 502395, 27482, '<td valign="top">Not bad, bet this is taken in Iceland.  Personally though I think it lacks a main subject and the image is too flat contrast wise for my personal taste.</td>', 'Not bad, bet this is taken in Iceland.  Personally though I think it lacks a main subject and the image is too flat contrast wise for my personal taste.', '2007-04-29 12:07:56.000000', NULL, 1),
(3592206, 502550, 27482, '<td valign="top">Pretty good, would rather have seen an even shallower DOF though as the backround is still a little bit too busy for my personal taste but pretty good like I said.  6 from me.</td>', 'Pretty good, would rather have seen an even shallower DOF though as the backround is still a little bit too busy for my personal taste but pretty good like I said.  6 from me.', '2007-04-29 12:08:53.000000', NULL, 1),
(3592213, 502637, 14614, '<td valign="top">there''s a lot working together in this B&amp;W - the light/dark areas create a great tension that pulls my eye into exploring the frame - don''t mind the chopped foot of the performer or the cut off person far right, really like the two men talking on left - - one of my favorites this challenge.  I am not really a "get out the ruler" on the topic but that''s what keeps this one from being one of my ribbon picks - you make great use of the vertical thirds -- better than most -- but the interection points of the horizontal and vertical grid don''t hold any interest for me and that keeps this one a bit shy in this contest. (sorry for the long explanation but I really like this one and was torn -- BOL)</td>', 'there''s a lot working together in this B&W - the light/dark areas create a great tension that pulls my eye into exploring the frame - don''t mind the chopped foot of the performer or the cut off person far right, really like the two men talking on left - - one of my favorites this challenge.  I am not really a "get out the ruler" on the topic but that''s what keeps this one from being one of my ribbon picks - you make great use of the vertical thirds -- better than most -- but the interection points of the horizontal and vertical grid don''t hold any interest for me and that keeps this one a bit shy in this contest. (sorry for the long explanation but I really like this one and was torn -- BOL)', '2007-04-29 12:11:01.000000', NULL, 1),
(3592218, 501711, 51802, '<td valign="top">This photo doesn''t do much to hold my interest.  The subject is just not that interesting.</td>', 'This photo doesn''t do much to hold my interest.  The subject is just not that interesting.', '2007-04-29 12:15:35.000000', NULL, 1),
(3592220, 502640, 51802, '<td valign="top">I''m not sure if this really fits the challenge or not.  The model is centered left/right, and is in the bottom half of the frame.  That doesn''t place her on any of the "thirds".</td>', 'I''m not sure if this really fits the challenge or not.  The model is centered left/right, and is in the bottom half of the frame.  That doesn''t place her on any of the "thirds".', '2007-04-29 12:18:00.000000', NULL, 1),
(3592224, 502232, 27482, '<td valign="top">Cleverly divided into three parts but still, something missing for me to give a higher rating than 5, apart from the division the composion is not guiding my eye towards any one point and frankly I don´t find this image very interesting, I think you can do better.</td>', 'Cleverly divided into three parts but still, something missing for me to give a higher rating than 5, apart from the division the composion is not guiding my eye towards any one point and frankly I don´t find this image very interesting, I think you can do better.', '2007-04-29 12:19:07.000000', NULL, 1),
(3592225, 500496, 51802, '<td valign="top">Sorry, but I really don''t like the processing done here.</td>', 'Sorry, but I really don''t like the processing done here.', '2007-04-29 12:19:10.000000', NULL, 1),
(3592226, 502349, 51802, '<td valign="top">I love the detail you captured here!</td>', 'I love the detail you captured here!', '2007-04-29 12:19:49.000000', NULL, 1),
(3592228, 502643, 51802, '<td valign="top">This is not a very photogenic subject.</td>', 'This is not a very photogenic subject.', '2007-04-29 12:20:43.000000', NULL, 1),
(3592229, 502477, 27482, '<td valign="top">Honestly this seems a bit "snapshottish" to me since you cut off her leg with the framing and the lighting and angle don´t add any interest to the shot.  Not bad but not good either, got a 5 from me.</td>', 'Honestly this seems a bit "snapshottish" to me since you cut off her leg with the framing and the lighting and angle don´t add any interest to the shot.  Not bad but not good either, got a 5 from me.', '2007-04-29 12:20:51.000000', NULL, 1),
(3592231, 502448, 51802, '<td valign="top">Great capture!  I love how his wing becomes a dominant element here.  Fits the challenge well!</td>', 'Great capture!  I love how his wing becomes a dominant element here.  Fits the challenge well!', '2007-04-29 12:22:05.000000', NULL, 1),
(3592233, 502637, 27482, '<td valign="top">I am wondering why you chose to not include his feet in the shot, makes me percieve the composition to be a bit random and poorly thought out.  Other than that pretty good but I am wondering if this shot would not have been stronger had there been some faces in the shot for me to connect to.  Tones and contrast are pretty good though, got a 6 from me.</td>', 'I am wondering why you chose to not include his feet in the shot, makes me percieve the composition to be a bit random and poorly thought out.  Other than that pretty good but I am wondering if this shot would not have been stronger had there been some faces in the shot for me to connect to.  Tones and contrast are pretty good though, got a 6 from me.', '2007-04-29 12:22:32.000000', NULL, 1),
(3592235, 500903, 51802, '<td valign="top">I don''t see this as meeting the challenge.  The main subject is too close to the corner to be considered following the rule of thirds.</td>', 'I don''t see this as meeting the challenge.  The main subject is too close to the corner to be considered following the rule of thirds.', '2007-04-29 12:23:29.000000', NULL, 1),
(3592237, 502356, 51802, '<td valign="top">This seems cropped a bit too tight.</td>', 'This seems cropped a bit too tight.', '2007-04-29 12:24:11.000000', NULL, 1),
