(3594869, 502553, 74588, '<td valign="top">8</td>', '8', '2007-04-30 07:46:25.000000', NULL, 1),
(3594871, 501650, 27482, '<td valign="top">Something about the backround bokeh is just not pleasing to my eye, too "sharp" for lack of a better word, actually the whole shot looks just a tad oversharpened.  I do like the lighting and colors though and still voted this a 6.</td>', 'Something about the backround bokeh is just not pleasing to my eye, too "sharp" for lack of a better word, actually the whole shot looks just a tad oversharpened.  I do like the lighting and colors though and still voted this a 6.', '2007-04-30 07:46:30.000000', NULL, 1),
