(3595567, 501017, 74209, '<td valign="top">Subtle and intense all at once!  Well composed.  Beautiful. 9</td>', 'Subtle and intense all at once!  Well composed.  Beautiful. 9', '2007-04-30 11:42:10.000000', NULL, 1),
